 52 | 
 53 |     function uniRouterA() public view returns (address) {
 54 |         return address(_uniRouter);
 55 |     }
 56 | 
 57 |     function _swap(
 58 |         ISwapHandler.SwapParams memory params
 59 |     ) internal override returns (uint256 amountOut) {
 60 |         if (params.underlyingIn == address(0)) revert InvalidInputToken();
 61 |         if (params.underlyingOut == address(0)) revert InvalidOutputToken();
 62 |         uint24 fee = params.feeTier;
 63 |         if (fee == 0) revert InvalidFeeTier();
 64 | 
 65 |         // Exact Input
 66 |         if (params.mode == ISwapHandler.SwapType.EXACT_INPUT) {
 67 |             amountOut = _uniRouter.exactInputSingle(
 68 |                 IV3SwapRouter.ExactInputSingleParams({
 69 |                     tokenIn: params.underlyingIn,
 70 |                     tokenOut: params.underlyingOut,
 71 |                     amountIn: params.amountIn,
 72 |                     amountOutMinimum: 0,
 73 |                     fee: fee,
 74 |                     recipient: address(this),
 75 |                     sqrtPriceLimitX96: 0
 76 |                 })
 77 |             );
 78 |             if (amountOut == 0) {
 79 |                 revert SwapFailed();
 80 |             }
 81 |             emit Swap(params.underlyingIn, params.underlyingOut, params.amountIn, amountOut);
 82 |             // Exact Output
 83 |         } else if (params.mode == ISwapHandler.SwapType.EXACT_OUTPUT) {
 84 |             uint256 amountIn = _uniRouter.exactOutputSingle(
 85 |                 IV3SwapRouter.ExactOutputSingleParams({
 86 |                     tokenIn: params.underlyingIn,
 87 |                     tokenOut: params.underlyingOut,
 88 |                     fee: fee,
 89 |                     recipient: address(this),
 90 |                     amountOut: params.amountOut,
 91 |                     amountInMaximum: params.amountIn,
 92 |                     sqrtPriceLimitX96: 0
 93 |                 })
 94 |             );
 95 |             if (amountIn < params.amountIn) {
 96 |                 IERC20(params.underlyingIn).safeTransfer(address(this), params.amountIn - amountIn);
 97 |             }
 98 |             emit Swap(params.underlyingIn, params.underlyingOut, amountIn, params.amountOut);
 99 |             amountOut = params.amountOut;
100 |         }
101 |     }
102 | }
